	@Test
	void spilledBindingSetContainsUsesTheBackingIndex() {
		AtomicInteger comparisons = new AtomicInteger();
		class Key extends MapBindingSet {
			@Override
			public boolean equals(Object other) {
				comparisons.incrementAndGet();
				return super.equals(other);
			}
		}
		try (MapDb3CollectionFactory factory = new MapDb3CollectionFactory(4)) {
			Set<BindingSet> keys = factory.createSetOfBindingSets(Key::new, n -> b -> b.hasBinding(n),
					n -> b -> b.getValue(n), n -> (v, b) -> b.setBinding(n, v));
			for (int i = 0; i < 64; i++) {
				keys.add(row(new Key(), i));
			}

			comparisons.set(0);
			assertFalse(keys.contains(row(new Key(), -1)));
			assertTrue(comparisons.get() < keys.size(),
					"a missing key must not be compared with every spilled element: " + comparisons.get());

			comparisons.set(0);
			assertTrue(keys.contains(row(new Key(), 63)));
			assertTrue(comparisons.get() < keys.size(),
					"a present key must not be found by scanning the spilled elements: " + comparisons.get());

			// Another BindingSet implementation honouring the BindingSet equality and hash contract is the same row.
			assertTrue(keys.contains(row(new MapBindingSet(), 31)));
			assertFalse(keys.contains(row(new MapBindingSet(), -1)));
		}
	}

	@Test
	void spilledIndexedSetMatchesEqualPlainNodeAndRetainsScopedAuthorityOnIteration() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		Object identityScope = new Object();
		BlankNodeAllocationScope allocation = new BlankNodeAllocationScope();
		RemoteBNode scoped = (RemoteBNode) RemoteBNode.newResponseScope(allocation, vf, identityScope, true)
				.map(vf.createBNode("remote-id"));
		BNode equalPlain = vf.createBNode(scoped.getID());

		assertEquals(scoped, equalPlain, "ordinary RDF blank-node equality is by the local alias ID");
		assertThrows(QueryEvaluationException.class,
				() -> RemoteBNode.toRemoteValue(equalPlain, identityScope, true, true),
				"an equal-looking plain probe must not inherit the scoped node's transport authority");

		try (MapDb3CollectionFactory factory = new MapDb3CollectionFactory(4)) {
			Set<BindingSet> keys = factory.createSetOfBindingSets(MapBindingSet::new,
					name -> row -> row.hasBinding(name),
					name -> row -> row.getValue(name), (name) -> (value, row) -> row.setBinding(name, value));
			for (int key = 0; key < 64; key++) {
				BNode value = key == 0 ? scoped : vf.createBNode("local-" + key);
				keys.add(nodeRow(vf, key, value));
			}

			assertEquals(64, keys.size(), "64 rows force the indexed set past its in-memory spill threshold");
			assertTrue(keys.contains(nodeRow(vf, 0, scoped)));
			assertTrue(keys.contains(nodeRow(vf, 0, equalPlain)),
					"lookup by an equal-ID plain node must find the scoped row");

			BindingSet restoredRow = keys.stream()
					.filter(row -> vf.createLiteral(0).equals(row.getValue("k")))
					.findFirst()
					.orElseThrow();
			RemoteBNode restored = assertInstanceOf(RemoteBNode.class, restoredRow.getValue("node"));
			assertTrue(RemoteBNode.sameTrustedIdentity(scoped, restored));
			assertEquals(vf.createBNode("remote-id"), RemoteBNode.toRemoteValue(restored, identityScope, true, true),
					"iteration after spilling must retain the original transport mapping");
		}
	}

	@Test
	void bindingSetMembershipIsTheSameBeforeAndAfterSpilling() {
		// Models an internal key such as PathIteration.ValuePair: it only equals its own class and does not share the
		// generic BindingSet hash, so a generic BindingSet with the same bindings is a different element to add().
		class Key extends MapBindingSet {
			@Override
			public int hashCode() {
				return super.hashCode() ^ 0x12345678;
			}

			@Override
			public boolean equals(Object other) {
				return other instanceof Key && super.equals(other);
			}
		}
		try (MapDb3CollectionFactory factory = new MapDb3CollectionFactory(4)) {
			Set<BindingSet> keys = factory.createSetOfBindingSets(Key::new, n -> b -> b.hasBinding(n),
					n -> b -> b.getValue(n), n -> (v, b) -> b.setBinding(n, v));
			// 3 rows stay in the in-memory hash set, 12 are wrapped for syncing, 64 are stored by MapDB.
			int size = 0;
			for (int spillStage : new int[] { 3, 12, 64 }) {
				while (size < spillStage) {
					assertTrue(keys.add(row(new Key(), size++)));
				}
				String stage = "with " + size + " elements";
				assertTrue(keys.contains(row(new Key(), 0)), stage);
				assertTrue(keys.contains(row(new Key(), size - 1)), stage);
				assertFalse(keys.contains(row(new Key(), -1)), stage);
				assertFalse(keys.contains(row(new MapBindingSet(), 0)), stage);
				assertFalse(keys.contains(null), stage);
				assertFalse(keys.contains("not a binding set"), stage);
				// contains agrees with add: the probed key is a duplicate exactly when contains reports it.
				assertFalse(keys.add(row(new Key(), 0)), stage);
				assertEquals(size, keys.size(), stage);
			}
		}
	}

	@Test
	void spilledValueAndGenericSetsAnswerNullAndForeignProbesWithoutThrowing() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		try (MapDb3CollectionFactory factory = new MapDb3CollectionFactory(4)) {
			Set<Value> values = factory.createValueSet();
			Set<String> strings = factory.createSet();
			for (int i = 0; i < 64; i++) {
				values.add(vf.createLiteral(i));
				strings.add("key" + i);
			}
			assertTrue(values.contains(vf.createLiteral(63)));
			assertFalse(values.contains(vf.createLiteral(-1)));
			assertFalse(values.contains(null));
			assertFalse(values.contains("63"));

			assertTrue(strings.contains("key63"));
			assertFalse(strings.contains("missing"));
			assertFalse(strings.contains(null));
			assertFalse(strings.contains(63));
		}
	}

	@Test
	void committingSetDelegatesContainsToItsIndexedBackingSet() {
		CountingSet backing = new CountingSet();
		backing.add("present");
		Set<String> set = new MapDb3CollectionFactory.CommitingSet<>(backing, 1, null);
		assertTrue(set.contains("present"));
		assertEquals(1, backing.containsCalls);
		assertFalse(set.contains("missing"));
		assertEquals(2, backing.containsCalls);
		assertTrue(set.containsAll(List.of("present")));
		assertEquals(3, backing.containsCalls);
		assertEquals(0, backing.iteratorCalls);
		// A MapDB-backed set rejects a null probe, and it can never hold null.
		assertFalse(set.contains(null));
		assertEquals(3, backing.containsCalls);
	}

	private static <B extends MapBindingSet> B row(B row, int key) {
		row.addBinding("k", SimpleValueFactory.getInstance().createLiteral(key));
		return row;
	}

	private static MapBindingSet nodeRow(SimpleValueFactory vf, int key, BNode node) {
		MapBindingSet row = new MapBindingSet();
		row.setBinding("k", vf.createLiteral(key));
		row.setBinding("node", node);
		return row;
	}

