	@Test
	void genericMapSpillsWithoutAnotherCollectionInitializingTheDatabase() {
		try (MapDb3CollectionFactory factory = new MapDb3CollectionFactory(1)) {
			Map<String, Long> map = factory.createMap();
			for (long index = 0; index < 16; index++) {
				map.put("key" + index, index);
			}
			for (long index = 0; index < 16; index++) {
				assertTrue(map.containsKey("key" + index));
				assertEquals(index, map.get("key" + index));
				assertEquals(index, map.remove("key" + index));
				assertFalse(map.containsKey("key" + index));
			}
			assertTrue(map.isEmpty());
		}
	}

	@Test
	void committingMapDelegatesKeyOperationsToItsIndexedBackingMap() {
		CountingMap backing = new CountingMap();
		backing.put("present", 1L);
		Map<String, Long> map = new MapDb3CollectionFactory.CommitingMap<>(backing, 1, null);
		assertEquals(1L, map.get("present"));
		assertEquals(1, backing.getCalls);
		assertTrue(map.containsKey("present"));
		assertEquals(1, backing.containsCalls);
		assertEquals(1L, map.remove("present"));
		assertEquals(1, backing.removeCalls);
		assertFalse(map.containsKey("missing"));
		assertEquals(2, backing.containsCalls);
	}

